""" For an HTML text, escapes characters that would be read as markup

    Adds in a line break after '>' to make reading the text easier
    """
def escape_html(text: Any) -> object {
    edited_text = str(text).replace("<", "&lt;").replace(">", "&gt;<br>");
    return edited_text;
}

